#!/bin/zsh
# Writes Nubble/Generated/Secrets.swift from ~/dev/pokpok-ai/.env (never committed). Run before building the hybrid build.
set -e
ENV=${1:-$HOME/dev/pokpok-ai/.env}
KEY=$(grep -E '^VERCEL_AI_GATEWAY_API_KEY=' "$ENV" | head -1 | cut -d= -f2- | tr -d '"' | tr -d "'")
mkdir -p "$(dirname "$0")/../Nubble/Generated"
cat > "$(dirname "$0")/../Nubble/Generated/Secrets.swift" <<SWIFT
// Generated by scripts/secrets.sh — not committed. The gateway key for the owner's own device only.
enum Secrets {
    static let aiGatewayKey = "$KEY"
}
SWIFT
echo "Secrets.swift written ($( [ -n "$KEY" ] && echo key present || echo NO KEY ))"
